struct RingBuffer {
    static const std::size_t MAX_CAPACITY = 1024;

    explicit RingBuffer(int capacity)
        : cap_(capacity < 1 ? 1 : (capacity > static_cast<int>(MAX_CAPACITY)
                                       ? static_cast<int>(MAX_CAPACITY)
                                       : capacity)),
          head_(0),
          tail_(0),
          count_(0) {}

    bool push(int value) {
        if (full()) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % cap_;
        ++count_;
        return true;
    }

    bool pop(int& out) {
        if (empty()) return false;
        out = data_[head_];
        head_ = (head_ + 1) % cap_;
        --count_;
        return true;
    }

    int size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == cap_; }

private:
    int data_[MAX_CAPACITY];
    int cap_;
    int head_;
    int tail_;
    int count_;
};
